-- migra-138 (12/10/2026): tres incoherencias entre paginas, corregidas en los nueve idiomas (pedido por Angel).
--  · Voto a envios: definitivo; solo se anula con la misma flecha en los primeros minutos (vote_undo_minutes). «Como funciona el δ» decia
--    «y cambiar de opinion» y «¿Que es Deltha?» «ni retirar». public/votar.php deja de admitir el cambio de sentido.
--  · Aura: «Como empezar» decia que sube cuando lo que comentas gusta; sube por enviar, por comentar y por llegar a portada (lib/aura.php).
--  · Moderacion: «¿Que es Deltha?» decia que modera una IA que vive en los servidores. La IA corre en equipos propios (local/moderador/),
--    revisa despues de publicar, nunca borra y decide siempre una persona (lib/moderacion.php). Las normas dejan de decir «servidores».
-- Son REPLACE del texto exacto que dejaron las migraciones anteriores: si un parrafo se edito en admin -> Paginas, ese idioma no cambia
-- y hay que pegarlo a mano.
SET NAMES utf8mb4;
UPDATE pages SET body = REPLACE(body, ', a favor o en contra, y cambiar de opinión.', ', a favor o en contra. El voto es definitivo: no se puede cambiar, y solo se puede anular pulsando otra vez la misma flecha en los primeros minutos.') WHERE slug = 'algoritmo';
UPDATE pages SET body = REPLACE(body, 'el voto es definitivo: una vez emitido no se puede cambiar ni retirar.', 'el voto a un envío es definitivo: una vez emitido no se puede cambiar, y solo se puede anular pulsando otra vez la misma flecha en los primeros minutos.') WHERE slug = 'que-es';
UPDATE pages SET body = REPLACE(body, 'sube cuando lo que envías llega a portada o lo que comentas gusta, y baja', 'sube cuando envías, cuando comentas y, sobre todo, cuando lo que envías llega a portada, y baja') WHERE slug = 'empezar';
UPDATE pages SET body = REPLACE(body, 'una IA que vive en nuestros servidores (ningún texto sale de ellos) hace', 'una IA que funciona en nuestros propios equipos (ningún texto pasa por terceros) hace') WHERE slug = 'normas';
UPDATE pages SET body = REPLACE(body, '<b>Modera una IA que vive en nuestros servidores.</b> Ningún envío ni comentario sale de ellos para ser revisado: no hay terceros mirando lo que escribes. Cuando duda, decide una persona.', '<b>Moderan personas, con la ayuda de una IA propia.</b> Todo se publica al momento. Después, cuando está activada, lo revisa una IA que funciona en nuestros propios equipos: no hay terceros mirando lo que escribes. La IA nunca borra nada: señala lo dudoso y, como mucho, lo oculta de forma provisional. La decisión es siempre de una persona.') WHERE slug = 'que-es';
UPDATE pages SET body = REPLACE(body, ', a favor o en contra, i canviar d''opinió.', ', a favor o en contra. El vot és definitiu: no es pot canviar, i només es pot anul·lar prement una altra vegada la mateixa fletxa els primers minuts.') WHERE slug = 'algoritmo.ca';
UPDATE pages SET body = REPLACE(body, 'el vot és definitiu: un cop emès no es pot canviar ni retirar.', 'el vot a un enviament és definitiu: un cop emès no es pot canviar, i només es pot anul·lar prement una altra vegada la mateixa fletxa els primers minuts.') WHERE slug = 'que-es.ca';
UPDATE pages SET body = REPLACE(body, 'puja quan el que envies arriba a portada o el que comentes agrada, i baixa', 'puja quan envies, quan comentes i, sobretot, quan el que envies arriba a portada, i baixa') WHERE slug = 'empezar.ca';
UPDATE pages SET body = REPLACE(body, 'una IA que viu als nostres servidors (cap text no en surt) fa', 'una IA que funciona als nostres propis equips (cap text no passa per tercers) fa') WHERE slug = 'normas.ca';
UPDATE pages SET body = REPLACE(body, '<b>Modera una IA que viu als nostres servidors.</b> Cap enviament ni comentari no en surt per ser revisat: no hi ha tercers mirant el que escrius. Quan dubta, decideix una persona.', '<b>Moderen persones, amb l''ajuda d''una IA pròpia.</b> Tot es publica al moment. Després, quan està activada, ho revisa una IA que funciona als nostres propis equips: no hi ha tercers mirant el que escrius. La IA no esborra mai res: assenyala el que és dubtós i, com a molt, ho amaga de manera provisional. La decisió és sempre d''una persona.') WHERE slug = 'que-es.ca';
UPDATE pages SET body = REPLACE(body, ', alde edo kontra, eta iritziz aldatu.', ', alde edo kontra. Botoa behin betikoa da: ezin da aldatu, eta lehen minutuetan gezi bera berriro sakatuta baino ezin da baliogabetu.') WHERE slug = 'algoritmo.eu';
UPDATE pages SET body = REPLACE(body, 'botoa behin betikoa da: behin emanda ezin da aldatu ez kendu.', 'bidalketa bati emandako botoa behin betikoa da: behin emanda ezin da aldatu, eta lehen minutuetan gezi bera berriro sakatuta baino ezin da baliogabetu.') WHERE slug = 'que-es.eu';
UPDATE pages SET body = REPLACE(body, 'igo egiten da bidaltzen duzuna azalera iristen denean edo komentatzen duzuna gustatzen denean, eta pixka bat', 'igo egiten da bidaltzen duzunean, iruzkintzen duzunean eta, batez ere, bidaltzen duzuna azalera iristen denean, eta pixka bat') WHERE slug = 'empezar.eu';
UPDATE pages SET body = REPLACE(body, 'gure zerbitzarietan bizi den AA batek (testu bat ere ez da haietatik ateratzen) lehen', 'gure ekipoetan dabilen AA batek (testu bat ere ez da hirugarrenen eskuetatik pasatzen) lehen') WHERE slug = 'normas.eu';
UPDATE pages SET body = REPLACE(body, '<b>Gure zerbitzarietan bizi den AA batek moderatzen du.</b> Bidalketa eta iruzkin bat ere ez da haietatik ateratzen berrikusteko: ez dago hirugarrenik idazten duzuna begira. Zalantza duenean, pertsona batek erabakitzen du.', '<b>Pertsonek moderatzen dute, gure AA baten laguntzaz.</b> Dena berehala argitaratzen da. Gero, aktibatuta dagoenean, gure ekipoetan dabilen AA batek berrikusten du: ez dago hirugarrenik idazten duzuna begira. AAk ez du inoiz ezer ezabatzen: zalantzazkoa dena seinalatzen du eta, gehienez ere, behin-behinean ezkutatzen du. Erabakia beti pertsona batena da.') WHERE slug = 'que-es.eu';
UPDATE pages SET body = REPLACE(body, ', a favor ou en contra, e cambiar de opinión.', ', a favor ou en contra. O voto é definitivo: non se pode cambiar, e só se pode anular premendo outra vez a mesma frecha nos primeiros minutos.') WHERE slug = 'algoritmo.gl';
UPDATE pages SET body = REPLACE(body, 'o voto é definitivo: unha vez emitido non se pode cambiar nin retirar.', 'o voto a un envío é definitivo: unha vez emitido non se pode cambiar, e só se pode anular premendo outra vez a mesma frecha nos primeiros minutos.') WHERE slug = 'que-es.gl';
UPDATE pages SET body = REPLACE(body, 'sobe cando o que envías chega a portada ou o que comentas gusta, e baixa', 'sobe cando envías, cando comentas e, sobre todo, cando o que envías chega a portada, e baixa') WHERE slug = 'empezar.gl';
UPDATE pages SET body = REPLACE(body, 'unha IA que vive nos nosos servidores (ningún texto sae deles) fai', 'unha IA que funciona nos nosos propios equipos (ningún texto pasa por terceiros) fai') WHERE slug = 'normas.gl';
UPDATE pages SET body = REPLACE(body, '<b>Modera unha IA que vive nos nosos servidores.</b> Ningún envío nin comentario sae deles para ser revisado: non hai terceiros mirando o que escribes. Cando dubida, decide unha persoa.', '<b>Moderan persoas, coa axuda dunha IA propia.</b> Todo se publica ao momento. Despois, cando está activada, revísao unha IA que funciona nos nosos propios equipos: non hai terceiros mirando o que escribes. A IA nunca borra nada: sinala o dubidoso e, como moito, ocúltao de forma provisional. A decisión é sempre dunha persoa.') WHERE slug = 'que-es.gl';
UPDATE pages SET body = REPLACE(body, ', up or down, and change their mind.', ', up or down. A vote is final: it cannot be changed, and it can only be undone by pressing the same arrow again within the first minutes.') WHERE slug = 'algoritmo.en';
UPDATE pages SET body = REPLACE(body, 'a vote is final: once cast it cannot be changed or withdrawn.', 'a vote on a post is final: once cast it cannot be changed, and it can only be undone by pressing the same arrow again within the first minutes.') WHERE slug = 'que-es.en';
UPDATE pages SET body = REPLACE(body, 'it rises when what you submit reaches the front page or what you comment is liked, and it drops', 'it rises when you submit, when you comment and, above all, when what you submit reaches the front page, and it drops') WHERE slug = 'empezar.en';
UPDATE pages SET body = REPLACE(body, 'an AI that lives on our servers (no text ever leaves them) does', 'an AI that runs on our own machines (no text ever goes through third parties) does') WHERE slug = 'normas.en';
UPDATE pages SET body = REPLACE(body, '<b>Moderation is done by an AI that lives on our servers.</b> No post or comment leaves them to be reviewed: there are no third parties looking at what you write. When it''s unsure, a person decides.', '<b>Moderation is done by people, with the help of our own AI.</b> Everything is published straight away. Afterwards, when it is switched on, it is reviewed by an AI that runs on our own machines: there are no third parties looking at what you write. The AI never deletes anything: it flags what looks doubtful and, at most, hides it provisionally. The decision is always made by a person.') WHERE slug = 'que-es.en';
UPDATE pages SET body = REPLACE(body, ', pour ou contre, et changer d''avis.', ', pour ou contre. Le vote est définitif : il ne peut pas être changé, et on ne peut l''annuler qu''en appuyant à nouveau sur la même flèche dans les premières minutes.') WHERE slug = 'algoritmo.fr';
UPDATE pages SET body = REPLACE(body, 'le vote est définitif : une fois émis, il ne peut être ni changé ni retiré.', 'le vote sur un envoi est définitif : une fois émis, il ne peut pas être changé, et on ne peut l''annuler qu''en appuyant à nouveau sur la même flèche dans les premières minutes.') WHERE slug = 'que-es.fr';
UPDATE pages SET body = REPLACE(body, 'il monte quand ce que vous envoyez atteint la une ou quand vos commentaires plaisent, et baisse', 'il monte quand vous envoyez, quand vous commentez et, surtout, quand ce que vous envoyez atteint la une, et baisse') WHERE slug = 'empezar.fr';
UPDATE pages SET body = REPLACE(body, 'une IA qui vit sur nos serveurs (aucun texte n''en sort) fait', 'une IA qui tourne sur nos propres machines (aucun texte ne passe par des tiers) fait') WHERE slug = 'normas.fr';
UPDATE pages SET body = REPLACE(body, '<b>La modération est faite par une IA qui vit sur nos serveurs.</b> Aucun envoi ni commentaire n''en sort pour être examiné : il n''y a pas de tiers qui regardent ce que tu écris. En cas de doute, c''est une personne qui décide.', '<b>La modération est faite par des personnes, avec l''aide de notre propre IA.</b> Tout est publié immédiatement. Ensuite, quand elle est activée, une IA qui tourne sur nos propres machines le relit : il n''y a pas de tiers qui regardent ce que tu écris. L''IA ne supprime jamais rien : elle signale ce qui est douteux et, tout au plus, le masque provisoirement. La décision revient toujours à une personne.') WHERE slug = 'que-es.fr';
UPDATE pages SET body = REPLACE(body, ', dafür oder dagegen, und seine Meinung ändern.', ', dafür oder dagegen. Die Stimme ist endgültig: Sie lässt sich nicht ändern und nur zurücknehmen, indem man in den ersten Minuten noch einmal denselben Pfeil drückt.') WHERE slug = 'algoritmo.de';
UPDATE pages SET body = REPLACE(body, 'ist eine Stimme endgültig: Einmal abgegeben, kann sie weder geändert noch zurückgenommen werden.', 'ist eine Stimme für einen Beitrag endgültig: Einmal abgegeben, lässt sie sich nicht ändern und nur zurücknehmen, indem man in den ersten Minuten noch einmal denselben Pfeil drückt.') WHERE slug = 'que-es.de';
UPDATE pages SET body = REPLACE(body, 'Sie steigt, wenn dein Beitrag die Titelseite erreicht oder dein Kommentar gefällt, und sinkt', 'Sie steigt, wenn du etwas einreichst, wenn du kommentierst und vor allem, wenn dein Beitrag die Titelseite erreicht, und sinkt') WHERE slug = 'empezar.de';
UPDATE pages SET body = REPLACE(body, 'eine KI, die auf unseren Servern lebt (kein Text verlässt sie), einen', 'eine KI, die auf unseren eigenen Rechnern läuft (kein Text geht über Dritte), einen') WHERE slug = 'normas.de';
UPDATE pages SET body = REPLACE(body, '<b>Moderiert wird von einer KI, die auf unseren Servern lebt.</b> Kein Beitrag und kein Kommentar verlässt sie zur Prüfung: Keine Dritten schauen mit, was du schreibst. Im Zweifel entscheidet ein Mensch.', '<b>Moderiert wird von Menschen, mit Hilfe einer eigenen KI.</b> Alles wird sofort veröffentlicht. Danach prüft es, wenn sie aktiviert ist, eine KI, die auf unseren eigenen Rechnern läuft: Keine Dritten schauen mit, was du schreibst. Die KI löscht nie etwas: Sie markiert Zweifelhaftes und blendet es höchstens vorläufig aus. Die Entscheidung trifft immer ein Mensch.') WHERE slug = 'que-es.de';
UPDATE pages SET body = REPLACE(body, ', a favore o contro, e cambiare idea.', ', a favore o contro. Il voto è definitivo: non si può cambiare, e si può annullare solo premendo di nuovo la stessa freccia nei primi minuti.') WHERE slug = 'algoritmo.it';
UPDATE pages SET body = REPLACE(body, 'il voto è definitivo: una volta espresso non si può cambiare né ritirare.', 'il voto a un invio è definitivo: una volta espresso non si può cambiare, e si può annullare solo premendo di nuovo la stessa freccia nei primi minuti.') WHERE slug = 'que-es.it';
UPDATE pages SET body = REPLACE(body, 'sale quando ciò che invii arriva in prima pagina o ciò che commenti piace, e scende', 'sale quando invii, quando commenti e, soprattutto, quando ciò che invii arriva in prima pagina, e scende') WHERE slug = 'empezar.it';
UPDATE pages SET body = REPLACE(body, 'un''IA che vive sui nostri server (nessun testo ne esce) fa', 'un''IA che funziona sulle nostre macchine (nessun testo passa da terzi) fa') WHERE slug = 'normas.it';
UPDATE pages SET body = REPLACE(body, '<b>Modera un''IA che vive sui nostri server.</b> Nessun invio né commento ne esce per essere revisionato: non ci sono terze parti a guardare cosa scrivi. Quando ha dubbi, decide una persona.', '<b>Moderano le persone, con l''aiuto di una nostra IA.</b> Tutto viene pubblicato subito. Poi, quando è attiva, lo rivede un''IA che funziona sulle nostre macchine: non ci sono terze parti a guardare cosa scrivi. L''IA non cancella mai nulla: segnala ciò che è dubbio e, al massimo, lo nasconde in via provvisoria. La decisione è sempre di una persona.') WHERE slug = 'que-es.it';
UPDATE pages SET body = REPLACE(body, ', a favor ou contra, e mudar de opinião.', ', a favor ou contra. O voto é definitivo: não pode ser alterado, e só pode ser anulado carregando outra vez na mesma seta nos primeiros minutos.') WHERE slug = 'algoritmo.pt';
UPDATE pages SET body = REPLACE(body, 'o voto é definitivo: uma vez dado, não pode ser alterado nem retirado.', 'o voto num envio é definitivo: uma vez dado, não pode ser alterado, e só pode ser anulado carregando outra vez na mesma seta nos primeiros minutos.') WHERE slug = 'que-es.pt';
UPDATE pages SET body = REPLACE(body, 'sobe quando o que envias chega à primeira página ou o que comentas agrada, e desce', 'sobe quando envias, quando comentas e, sobretudo, quando o que envias chega à primeira página, e desce') WHERE slug = 'empezar.pt';
UPDATE pages SET body = REPLACE(body, 'uma IA que funciona nos nossos servidores (nenhum texto sai deles) faz', 'uma IA que funciona nos nossos próprios equipamentos (nenhum texto passa por terceiros) faz') WHERE slug = 'normas.pt';
UPDATE pages SET body = REPLACE(body, '<b>Quem modera é uma IA que vive nos nossos servidores.</b> Nenhum envio ou comentário sai deles para ser analisado: ninguém de fora lê o que é escrito aqui. Na dúvida, decide uma pessoa.', '<b>Quem modera são pessoas, com a ajuda de uma IA própria.</b> Tudo é publicado de imediato. Depois, quando está ativada, é revisto por uma IA que funciona nos nossos próprios equipamentos: ninguém de fora lê o que é escrito aqui. A IA nunca apaga nada: assinala o que é duvidoso e, no máximo, oculta-o provisoriamente. A decisão é sempre de uma pessoa.') WHERE slug = 'que-es.pt';
